import{_ as a,o as i,c as n,ah as s}from"./chunks/framework.BBwyAVS8.js";const o="/projects/JetAcker/en/jetacker-jetson-nano/assets/image2.C6-fOXe5.png",r="/projects/JetAcker/en/jetacker-jetson-nano/assets/image3.CcOM2IIQ.jpeg",c="/projects/JetAcker/en/jetacker-jetson-nano/assets/image4.CHeXCIG_.jpeg",l="/projects/JetAcker/en/jetacker-jetson-nano/assets/image6.DMY9IstT.png",d="/projects/JetAcker/en/jetacker-jetson-nano/assets/image7.BW8J70nm.png",p="/projects/JetAcker/en/jetacker-jetson-nano/assets/image8.BkoMV5lW.png",h="/projects/JetAcker/en/jetacker-jetson-nano/assets/image9.BaETxBWR.png",g="/projects/JetAcker/en/jetacker-jetson-nano/assets/image10.CqICKy0C.png",m="/projects/JetAcker/en/jetacker-jetson-nano/assets/image11.BEMdUtvk.png",u="/projects/JetAcker/en/jetacker-jetson-nano/assets/image12.Z6rFE688.png",b="/projects/JetAcker/en/jetacker-jetson-nano/assets/image13.vhdhRJgC.png",A="/projects/JetAcker/en/jetacker-jetson-nano/assets/image14.BY5LYkqT.png",t="data:image/png;base64,",j=JSON.parse('{"title":"3. Lidar Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.lidar_course.md","filePath":"docs/3.lidar_course.md"}'),v={name:"docs/3.lidar_course.md"};function f(k,e,y,w,C,I){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-lidar-course" tabindex="-1">3. Lidar Course <a class="header-anchor" href="#_3-lidar-course" aria-label="Permalink to &quot;3. Lidar Course&quot;">​</a></h1><h2 id="_3-1-introduction-to-lidar" tabindex="-1">3.1 Introduction to Lidar <a class="header-anchor" href="#_3-1-introduction-to-lidar" aria-label="Permalink to &quot;3.1 Introduction to Lidar&quot;">​</a></h2><h3 id="_3-1-1-preface" tabindex="-1">3.1.1 Preface <a class="header-anchor" href="#_3-1-1-preface" aria-label="Permalink to &quot;3.1.1 Preface&quot;">​</a></h3><p>Lidar, a high-precision and high-speed remote sensing technology, is pivotal in numerous domains, including map creation, autonomous driving, environmental perception, and robot navigation. This document provides an overview of Lidar&#39;s principles, components, working mechanisms, application areas, advantages, and development trends.</p><p>In autonomous driving and intelligent transportation, Lidar assumes a critical role by offering real-time perception of obstacles, pedestrians, and vehicles on the road, providing precise distance and location information. In robot navigation and environmental perception, Lidar contributes by furnishing accurate maps and information about the surrounding environment. Furthermore, Lidar finds extensive applications in areas such as 3D modeling, map creation, safety monitoring, and remote sensing mapping.</p><img loading="lazy" height="330" width="611" class="common_img" src="'+o+'"><h3 id="_3-1-2-lidar-composition-and-classification" tabindex="-1">3.1.2 Lidar Composition and Classification <a class="header-anchor" href="#_3-1-2-lidar-composition-and-classification" aria-label="Permalink to &quot;3.1.2 Lidar Composition and Classification&quot;">​</a></h3><p>Lidar is composed of essential components such as a laser emitter, receiver, photodetector, scanning mechanism, and angle resolver. The laser emitter produces laser beams, while the receiver and photodetector capture reflected light signals. The scanning mechanism is responsible for surveying the surrounding environment, and the angle resolver assists in determining the position of target objects.</p><p>Lidar can be categorized into various types based on the scanning method:</p><p><strong>Rotating Lidar</strong>: Achieves omnidirectional scanning horizontally by rotating the emitter or scanning mechanism. Known for high scanning speed and measurement accuracy, it is widely applied in areas such as autonomous driving, 3D environmental modeling, and map creation.</p><p><strong>Solid-State Lidar</strong>: Utilizes solid-state laser emitters, eliminating the need for rotating components. Compact, lightweight, and energy-efficient, solid-state lidar is suitable for applications like mobile devices, drones, and robots.</p><p><strong>Mechanical Lidar</strong>: Employs mechanical components like rotating mirrors or prisms for laser beam scanning. Although offering longer measurement distances and higher accuracy, mechanical lidar tends to have slower scanning speeds. It is commonly used in terrain measurement, building scanning, and navigation.</p><p><strong>Phase-Modulated Lidar</strong>: Measures the distance between target objects and the lidar by altering the phase of the laser beam. Known for high measurement accuracy and a large measurement range, phase-modulated lidar is extensively used in map creation, surveying, and industrial applications.</p><p><strong>Flash Lidar</strong>: Utilizes brief, high-power laser pulses to illuminate the entire scene simultaneously. It captures reflected light signals through an array of receivers, making it suitable for high-speed and high-resolution applications, including rapid scene capture and motion tracking.</p><h3 id="_3-1-3-switch-lidar-version" tabindex="-1">3.1.3 Switch Lidar Version <a class="header-anchor" href="#_3-1-3-switch-lidar-version" aria-label="Permalink to &quot;3.1.3 Switch Lidar Version&quot;">​</a></h3><p>The robot provides two Lidar options, and the default Lidar version in the system image is G4 Lidar. Therefore, please confirm the Lidar version upon you receiving the robot kit.</p><div class="common_img" style="display:flex;text-align:center;flex-direction:row;"><div style="display:flex;flex-direction:column;align-items:center;row-gap:10px;width:48%;"><img loading="lazy" height="500" width="580" src="'+r+'"><span>A1 Lidar </span></div><div style="display:flex;flex-direction:column;align-items:center;row-gap:10px;width:48%;"><img loading="lazy" height="500" width="580" src="'+c+'"><span>G4 Lidar </span></div></div><p>(1) Start the robot, and connect it to NoMachine according to the instructions provided in <a href="./1.getting_ready.html#development-environment-setup-and-configuration">Establish Development Environment</a>.</p><p>(2) After successful connection, double-click <img loading="lazy" height="67" width="48" src="'+l+'">.</p><img loading="lazy" height="368" width="751" class="common_img" src="'+d+'"><p>(3) Click the drop-down menu on the Lidar tab, and select the Lidar model that matchs your robot, such as selecting &quot;<strong>G4</strong>&quot;, then click &quot;<strong>Save</strong>&quot; and &quot;<strong>Apply</strong>&quot;.</p><img loading="lazy" height="370" width="756" class="common_img" src="'+p+'"><p>(5) After you reselect the Lidar version, the below prompt will appear.</p><img loading="lazy" height="362" width="752" class="common_img" src="'+h+'"><p>(6) After the system completes a restart, click-on &quot;<strong>Quit</strong>&quot; icon.</p><img loading="lazy" height="367" width="753" class="common_img" src="'+g+'"><p>(7) After the system completes a restart, click-on &quot;<strong>Quit</strong>&quot; icon.</p><img loading="lazy" height="225" width="730" class="common_img" src="'+m+'"><h2 id="_3-2-lidar-working-and-ranging-principle" tabindex="-1">3.2 Lidar Working and Ranging Principle <a class="header-anchor" href="#_3-2-lidar-working-and-ranging-principle" aria-label="Permalink to &quot;3.2 Lidar Working and Ranging Principle&quot;">​</a></h2><h3 id="_3-2-1-lidar-ranging" tabindex="-1">3.2.1 Lidar Ranging <a class="header-anchor" href="#_3-2-1-lidar-ranging" aria-label="Permalink to &quot;3.2.1 Lidar Ranging&quot;">​</a></h3><p>Two common methods are employed by Lidar to determine the distance to a target: triangulation and Time of Flight (TOF).</p><p>In the case of TOF, as depicted in the diagram, the Lidar initially projects light onto the object. The object reflects the light directly back to the Lidar, which calculates the time it takes for the light to return. The distance between the object and the Lidar is then obtained by multiplying this time by the speed of light.</p><img loading="lazy" height="311" width="820" class="common_img" src="'+u+'"><p>In triangulation, as illustrated in the diagram, the Lidar undergoes adjustments during manufacturing to ensure that the light does not directly strike the object. Instead, it is projected at a specific angle, a pre-set value that remains constant during operation. The distance from the object to the Lidar can be calculated by incorporating this angle into trigonometric functions.</p><img loading="lazy" height="313" width="809" class="common_img" src="'+b+'"><h3 id="_3-2-2-lidar-working-result" tabindex="-1">3.2.2 Lidar Working Result <a class="header-anchor" href="#_3-2-2-lidar-working-result" aria-label="Permalink to &quot;3.2.2 Lidar Working Result&quot;">​</a></h3><p>Its working result is as follows. Lidar will emit light and shine it on the object surface. When receiving the light reflected by the object, Lidar will mark the contour of the object at the position where the light is reflected.</p><img loading="lazy" height="556" width="770" class="common_img" src="'+A+'"><h2 id="_3-3-lidar-obstacle-avoidance" tabindex="-1">3.3 Lidar Obstacle Avoidance <a class="header-anchor" href="#_3-3-lidar-obstacle-avoidance" aria-label="Permalink to &quot;3.3 Lidar Obstacle Avoidance&quot;">​</a></h2><p>The robot senses the distance between itself and an object directly in front of it. Depending on the configured distance, the robot will either turn left or right to avoid obstacles. If no obstacles are detected, it will proceed to move forward.</p><p>This game can be activated in two ways: either through a mobile app or by issuing commands after establishing a remote connection to the system.</p><p>For instructions on app connection, please consult the tutorial located in <a href="./1.getting_ready.html#app-control">&#39;1 Quick Start Guide/JetAcker User Manual/ 1.5 APP Control&#39;</a></p><p>(1) Start the robot, and access the robot system desktop using nomachine.</p><p>(2) Click-on <img loading="lazy" height="38" width="45" src="'+t+'">to open the command-line terminal.</p><p>(3) Execute the command and press Enter to deactivate the automatic start service for the app.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl stop start_app_node.service</span></span></code></pre></div><p>(4) Enter the command and press Enter to start the robot&#39;s auto-start program:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch app lidar_node.launch.py debug:=true</span></span></code></pre></div><p>(5) Open a new command line terminal, type the command, and press Enter to access the Lidar feature</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/enter std_srvs/srv/Trigger {}</span></span></code></pre></div><p>(6) Enter the command and hit Enter to launch Lidar obstacle avoidance game.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 1}&quot;</span></span></code></pre></div><p>(7) If you need to stop the current function, simply enter the command in the current command line terminal.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 0}&quot;</span></span></code></pre></div><p>(8) To exit the game mode, simply press &quot;<strong>Ctrl+C</strong>&quot; in the terminal interface at step 4) or 5).</p><h2 id="_3-4-lidar-following" tabindex="-1">3.4 Lidar Following <a class="header-anchor" href="#_3-4-lidar-following" aria-label="Permalink to &quot;3.4 Lidar Following&quot;">​</a></h2><p>The robot monitors the distance between itself and an object directly in front. If the distance exceeds 35cm, it will track the object ahead. If the distance is less than 35cm, it will reverse. The robot automatically halts when the distance directly in front is detected as 35cm.</p><p>This game can be activated in two ways: either through a mobile app or by issuing commands after establishing a remote connection to the system.</p><p>For instructions on app connection, please consult the tutorial located in <a href="./1.getting_ready.html#app-control">1 Quick Start Guide/ JetAcker User Manual/ 1.5 App Control</a>.</p><p>(1) Start the robot, and access the robot system desktop using NoMachine.</p><p>(2) Click-on <img loading="lazy" height="38" width="45" src="'+t+'">to start the command line terminal.</p><p>(3) Execute the command and press Enter to deactivate the automatic start service for the app.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo systemctl stop start_app_node.service</span></span></code></pre></div><p>(3) Run the command to enable the local services for app-related game and chassis control services.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch app lidar_node.launch.py debug:=true</span></span></code></pre></div><p>(4) Open a new command-line terminal, and execute the command, then press Enter to start the Lidar game.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/enter std_srvs/srv/Trigger {}</span></span></code></pre></div><p>(5) Enter the command and hit Enter to launch Lidar following game.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 2}&quot;</span></span></code></pre></div><p>(6) If you need to stop the current function, simply enter the command in the current command line terminal.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 service call /lidar_app/set_running interfaces/srv/SetInt64 &quot;{data: 0}&quot;</span></span></code></pre></div><p>(7) To exit the game mode, simply press &quot;<strong>Ctrl+C</strong>&quot; in the terminal interface at step (4) or (5).</p>',72)])])}const L=a(v,[["render",f]]);export{j as __pageData,L as default};
